SELECT p.id, p.symbol, p.close_reason, TIMESTAMPDIFF(MICROSECOND, wb.executed_at, p.opened_at)/1000 AS buy_to_paper_open_ms, ws.execution_reason AS sell_reason, TIMESTAMPDIFF(MICROSECOND, ws.executed_at, p.closed_at)/1000 AS sell_to_paper_close_ms FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.wallet_trade wb ON wb.signal_id=p.signal_id AND wb.side='BUY' LEFT JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id=p.signal_id LEFT JOIN crypto_ai.wallet_trade ws ON ws.side='SELL' AND (ws.execution_key LIKE CONCAT('POSITION:', m.id, ':%') OR (p.exit_signal_id IS NOT NULL AND ws.signal_id=p.exit_signal_id)) WHERE p.opened_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-16 00:00:00' ORDER BY p.id LIMIT 80;